private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        int octet = bb.get(i) & 0xFF;
        if (octet <= 0x7F) {
            sb.append((char) octet);
            i++;
        } else if (octet <= 0xDF) {
            if (i + 1 >= bb.limit()) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            int octet2 = bb.get(i + 1) & 0xFF;
            sb.append((char) (((octet & 0x1F) << 6) | (octet2 & 0x3F)));
            i += 2;
        } else if (octet <= 0xEF) {
            if (i + 2 >= bb.limit()) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            int octet2 = bb.get(i + 1) & 0xFF;
            int octet3 = bb.get(i + 2) & 0xFF;
            sb.append((char) (((octet & 0x0F) << 12) | ((octet2 & 0x3F) << 6) | (octet3 & 0x3F)));
            i += 3;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return i;
}
