private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node has a left child
    if (node.left == null) {
        return node;
    }

    // Get the left child
    TreeNode<T> left = node.left;

    // Set the parent of the left child to be the parent of the node
    left.parent = node.parent;

    // Set the left child of the parent to be the left child of the node
    if (node.parent != null) {
        node.parent.left = left;
    }

    // Set the right child of the node to be the right child of the left child
    node.right = left.right;

    // Set the left child of the left child to be the node
    left.right = node;

    // Update the height of the node
    node.height = Math.max(getHeight(node.left), getHeight(node.right)) + 1;

    // Return the new parent of the node
    return left;
}
