public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    if (file.isDirectory()) {
        forceDeleteDirectoryOnExit(file);
    } else {
        forceDeleteFileOnExit(file);
    }
}

private static void forceDeleteDirectoryOnExit(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }

    if (!directory.isDirectory()) {
        throw new IOException("File " + directory + " is not a directory");
    }

    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            forceDeleteOnExit(file);
        }
    }

    directory.deleteOnExit();
}

private static void forceDeleteFileOnExit(File file) throws IOException {
    if (!file.exists()) {
        return;
    }

    if (!file.isFile()) {
        throw new IOException("File " + file + " is not a file");
    }

    file.deleteOnExit();
}

