public void addMessage(final LogRecord lr) {
    // Check if the log record is null
    if (lr == null) {
        throw new IllegalArgumentException("Log record cannot be null");
    }

    // Post a request to the SwingThread to add the log record
    SwingUtilities.invokeLater(new Runnable() {
        @Override
        public void run() {
            // Get the LogTable instance
            LogTable logTable = LogTable.getInstance();

            // Add the log record to the table
            logTable.addLogRecord(lr);
        }
    });
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the input graph is valid
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input graph or result map is null");
    }

    // Create a new graph
    Graph<V, E> newGraph = new Graph<>();

    // Add all vertices from the result map to the new graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        newGraph.addVertex(entry.getKey(), entry.getValue());
    }

    // Add all edges from the target graph to the new graph
    for (V vertex : target.getVertices()) {
        for (E edge : target.getEdges(vertex)) {
            V targetVertex = target.getOtherVertex(vertex, edge);
            if (resultMap.containsKey(targetVertex.getLabel())) {
                newGraph.addEdge(vertex, resultMap.get(targetVertex.getLabel()), edge);
            }
        }
    }

    // Return the new graph
    return newGraph;
}

