public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }

    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.putByte((byte) c);
        } else if (c < 0x800) {
            lb.putByte((byte) (0xc0 | (c >> 6)));
            lb.putByte((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0xd800 || c >= 0xe000) {
            lb.putByte((byte) (0xe0 | (c >> 12)));
            lb.putByte((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.putByte((byte) (0x80 | (c & 0x3f)));
        } else {
            // surrogate pair
            // first surrogate
            lb.putByte((byte) (0xf0 | (c >> 18)));
            lb.putByte((byte) (0x80 | ((c >> 12) & 0x3f)));
            lb.putByte((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.putByte((byte) (0x80 | (c & 0x3f)));

            // second surrogate
            if (i == strLen - 1) {
                throw new IllegalArgumentException("Invalid UTF-16 data");
            }
            i++;
            char d = str.charAt(i);
            if (d < 0xdc00 || d >= 0xe000) {
                throw new IllegalArgumentException("Invalid UTF-16 data");
            }
            lb.putByte((byte) (0x80 | (d >> 6)));
            lb.putByte((byte) (0x80 | (d & 0x3f)));
        }
    }
    return lb;
}
