public final MatchResult match(CharSequence uri) {
    // Check if the uri is null or empty
    if (uri == null || uri.length() == 0) {
        throw new IllegalArgumentException("uri cannot be null or empty");
    }

    // Initialize the match result
    MatchResult result = new MatchResult();

    // Iterate over the template tokens
    for (int i = 0; i < templateTokens.length; i++) {
        // Get the current token
        String token = templateTokens[i];

        // Check if the token is a wildcard
        if (token.equals("*")) {
            // Add the wildcard to the result
            result.addWildcard(i);
        } else {
            // Check if the token is a variable
            if (token.startsWith("{") && token.endsWith("}")) {
                // Get the variable name
                String variableName = token.substring(1, token.length() - 1);

                // Check if the variable is present in the uri
                if (uri.indexOf(variableName) == -1) {
                    // No match
                    return null;
                }

                // Add the variable to the result
                result.addVariable(variableName, i);
            } else {
                // Check if the token is a literal
                if (!token.equals(uri.charAt(i))) {
                    // No match
                    return null;
                }
            }
        }
    }

    // Return the match result
    return result;
}
