public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    if (node.getPrevious() == null && node.getNext() == null) {
        // Node is the only element in the list, so we need to remove it
        // and set the list head to null
        listHead = null;
        return true;
    } else if (node.getPrevious() == null) {
        // Node is the first element in the list, so we need to remove it
        // and set the next node to be the new head of the list
        ListNodeImpl<E> nextNode = node.getNext();
        nextNode.setPrevious(null);
        return true;
    } else if (node.getNext() == null) {
        // Node is the last element in the list, so we need to remove it
        // and set the previous node to be the new tail of the list
        ListNodeImpl<E> previousNode = node.getPrevious();
        previousNode.setNext(null);
        return true;
    } else {
        // Node is in the middle of the list, so we need to remove it
        // and update the previous and next nodes to point to each other
        ListNodeImpl<E> previousNode = node.getPrevious();
        ListNodeImpl<E> nextNode = node.getNext();
        previousNode.setNext(nextNode);
        nextNode.setPrevious(previousNode);
        return true;
    }
}
